import{_ as i,c as r,o as l,ag as t}from"./chunks/framework.piE7uVCg.js";const h=JSON.parse('{"title":"Cossuel","description":"","frontmatter":{},"headers":[],"relativePath":"electricite/cossuel.md","filePath":"electricite/cossuel.md"}'),s={name:"electricite/cossuel.md"};function a(o,e,n,c,d,u){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="cossuel" tabindex="-1"><a href="./readme.html">Cossuel</a> <a class="header-anchor" href="#cossuel" aria-label="Permalink to &quot;[Cossuel](readme.md)&quot;">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Le COSSUEL est une entité à but non lucratif qui a pour vocation principale de veiller au renforcement de la sécurité des biens et des personnes à travers un contrôle strict du respect des normes de sécurité prescrites en matière d’installation électriques.</p><h2 id="installation-d-un-coffret" tabindex="-1">Installation d&#39;un coffret <a class="header-anchor" href="#installation-d-un-coffret" aria-label="Permalink to &quot;Installation d&#39;un coffret&quot;">​</a></h2><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li>Vérifier la terre</li><li>utiliser des peignes pour relier les disjoncteurs</li><li>Equilibrer les phases</li><li>Utiliser des sections de 6mm² entre le sectionneur, le différentiel et les disjoncteurs modulaires</li></ul><h3 id="schema-d-installtion" tabindex="-1">Schéma d&#39;installtion <a class="header-anchor" href="#schema-d-installtion" aria-label="Permalink to &quot;Schéma d&#39;installtion&quot;">​</a></h3><ol><li>Sectionneur</li><li>Disjoncteur différenciel 30A (max 8 modulaires) <ol><li>Disjoncteur modulaire 10A</li><li>Disjoncteur modulaire 20A</li></ol></li><li>Disjoncteur différenciel 30A <ol><li>Disjoncteur modulaire 10A</li><li>Disjoncteur modulaire 20A</li></ol></li></ol><h2 id="points-de-controle" tabindex="-1">Points de controle <a class="header-anchor" href="#points-de-controle" aria-label="Permalink to &quot;Points de controle&quot;">​</a></h2><ol><li>Masure de la valeur de terre</li><li>Mesure d&#39;isolement des cables</li><li>Mesure d&#39;isolement des protections</li><li>Vérification des sections de conducteurs</li><li>Vérification fonctionnement des dispositifs différentiels</li><li>Vérification de la continuité des conducteurs de terre</li><li>Vérification des IP par rapport aux milieux humides</li><li>Vérification des serrages des câbles au niveau des borniers</li><li>Respect des repères par rapport aux schémas visés</li></ol>',10)])])}const m=i(s,[["render",a]]);export{h as __pageData,m as default};
